# Let me try flood fill connected regions theory
from collections import deque

def flood_fill(grid, start_r, start_c, target_val, block_val):
    """Flood fill all cells with target_val starting from start_r,start_c, blocking at block_val"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = deque([(start_r, start_c)])
    visited.add((start_r, start_c))

    regions = []

    while queue:
        r, c = queue.popleft()
        regions.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == target_val:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return regions

